const importScenario = {
  name: "Import Lab notebook schema into testVault",
  input: "Import discourse graph schema; Choose schema file (stubbed to dg-schema-lab-notebook.json); resolve conflicts; Import selected",
  expected: "preview with new/existing counts; conflict step; Import complete notice",
  setup: async (ctx) => { await stubDialogs(ctx, `${EXPORT_OUT}/unused.json`); },
  run: async (ctx) => {
    const { client, json } = ctx;
    await runCommand(ctx, "import-dg-schema");
    await waitText(ctx, "Choose schema file");
    await shot(ctx, "import-01-pick");
    await clickButton(ctx, "Choose schema file");
    await waitText(ctx, "Import schema preview");
    await shot(ctx, "import-02-preview");
    await scrollPanel(ctx, "Relation types");
    await shot(ctx, "import-03-preview-relations");
    await clickButton(ctx, "Choose what to keep", { startsWith: true });
    await waitText(ctx, "Every field starts on your value");
    await shot(ctx, "import-04-conflicts");
    // Take the file's values for Question, and the file's template body to show the copy note.
    await client.evaluate(`const sec = Array.from(document.querySelectorAll(${json(`${MODAL} section`)}))
      .find((s) => s.querySelector("h5")?.textContent.trim().startsWith("Question") && !s.querySelector("h5").textContent.includes("template"));
