      const panel = document.querySelector(${json(`${MODAL} .max-h-96`)}); panel.scrollTop = 0; return true;`);
    await shot(ctx, "import-05-conflicts-chosen");
    await client.evaluate(`const panel = document.querySelector(${json(`${MODAL} .max-h-96`)}); panel.scrollTop = panel.scrollHeight; return true;`);
    await shot(ctx, "import-06-conflicts-templates");
    await clickButton(ctx, "Import selected");
    await client.waitFor(`return !!Array.from(document.querySelectorAll(".notice")).find((n) => n.textContent.includes("Import complete"));`, { label: "import notice", timeout: 15000 });
    await shot(ctx, "import-07-notice", ".notice-container");
    return client.evaluate(`return Array.from(document.querySelectorAll(".notice")).map((n) => n.textContent).join(" | ");`);
  },
  expect: (notice) => ({ pass: /Import complete/.test(notice), actual: notice }),
  teardown: async (ctx) => {
    const { client, vault } = ctx;
    await unstubDialogs(ctx);
    // Put testVault back exactly as backed up: settings file and templates folder.
    const root = vault.root;
    copyFileSync(`${BACKUP}/data.json`, path.join(vault.pluginDir, "data.json"));
    const tplDir = path.join(root, "templates");
    const keep = new Set(readdirSync(`${BACKUP}/templates`));
    for (const f of readdirSync(tplDir)) if (!keep.has(f)) rmSync(path.join(tplDir, f));
    for (const f of keep) copyFileSync(`${BACKUP}/templates/${f}`, path.join(tplDir, f));
    await client.reloadPlugin({ pluginId: vault.pluginId, pluginFolder: path.basename(vault.pluginDir) });
  },
};

export default [exportScenario, importScenario];
